def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split on '-' to separate version and pre-release
        if '-' in v_without_build:
            version_part, prerelease_part = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease.append((0, int(ident)))
                else:
                    prerelease.append((1, ident))
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def sort_key(v):
        parsed = parse_version(v)
        major, minor, patch, prerelease = parsed

        if prerelease is None:
            # No pre-release sorts after pre-release
            return (major, minor, patch, 1, ())
        else:
            # Has pre-release sorts before no pre-release
            return (major, minor, patch, 0, tuple(prerelease))

    # Sort using stable sort (maintains input order for equal precedence)
    return sorted(versions, key=sort_key)

